import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def g2(a, b):
    while b:
        a, b = b, a % b
    return a
r = 0
for x in a:
    if g2(x, 10) == 1:
        r ^= x
print(r)

